function shop(){const category=decodeURIComponent(route.split('/')[2]||'');return `<main class="container"><div class="page-title"><div><div class="eyebrow">The considered collection</div><h1>${categoryHeading(category)}</h1><p>${categoryIntro(category)}</p></div><span id="result-count" class="mini muted"></span></div><div class="filters" id="shop-filters"><input type="search" id="search" placeholder="Search your next favourite…" aria-label="Search products"><select id="category" aria-label="Category"><option value="">All categories</option>${CATS.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select><select id="size-filter" aria-label="Size"><option value="">Every size</option>${[...SIZES,'One Size'].map(s=>`<option>${s}</option>`).join('')}</select><select id="price-filter" aria-label="Maximum price"><option value="99999">Any price</option value="1000">Under ₹1,000</option><option value="2000">Under ₹2,000</option><option value="3000">Under ₹3,000</option></select><select id="sort" aria-label="Sort products"><option value="featured">Featured</option><option value="asc">Price: low to high</option><option value="desc">Price: high to low</option></select><label class="check"><input type="checkbox" id="available"> In stock only</label></div><div id="catalog" class="products"></div></main>`;}
function filterShop(){let q=$('#search').value.toLowerCase(),cat=$('#category').value,size=$('#size-filter').value;let ps=db.products.filter(p=>p.name.toLowerCase().includes(q)&&(!cat||p.category===cat)&&(!size||size in p.stock)&&p.price<=Number($('#price-filter').value)&&(!$('#available').checked||(size?p.stock[size]>0:totalStock(p)>0)));if($('#sort').value!=='featured')ps.sort((a,b)=>($('#sort').value==='asc'?1:-1)*(a.price-b.price));$('#catalog').innerHTML=ps.length?ps.map(card).join(''):'<div class="empty" style="grid-column:1/-1">No pieces match your filters. Try another size or category.</div>';$('#result-count').textContent=ps.length+' considered essentials';}
