function cartItems(){return db.cart.map(x=>({...x,p:db.products.find(p=>p.id===x.id)})).filter(x=>x.p);}
function cartTotals(){const subtotal=sum(cartItems().map(x=>x.p.price*x.qty)),tax=Math.round(subtotal*5)/100;return{subtotal,tax,total:subtotal+tax};}
function orderSummary(button=true){const t=cartTotals();return `<h3>Your order summary</h3><div class="line"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="line"><span>GST <span title="A fixed illustrative rate of 5%, not a tax determination.">ⓘ (5% demo)</span></span><span>${money(t.tax)}</span></div><div class="line"><span>Delivery</span><span>Complimentary</span></div><div class="line total"><strong>Total</strong><strong>${money(t.total)}</strong></div>${button?'<a href="#/checkout" class="btn full">Continue to address & payment ↗</a>':''}<p class="notice">This is a demo store. No money will be charged.</p>`;}
function cart(){const items=cartItems();return `<main class="container"><div class="page-title"><div><div class="eyebrow">Your considered choices</div><h1>The shopping bag.</h1><p>${sum(items.map(x=>x.qty))} pieces, ready for your everyday.</p></div><a class="text-btn" href="#/shop">Continue exploring ↗</a></div>${items.length?`<div class="cart-layout"><div>${items.map(x=>`<div class="cart-row"><div class="product-art">${art(x.p)}</div><div><h3>${esc(x.p.name)}</h3><p class="mini muted">${x.p.id} / Size ${x.size} / ${money(x.p.price)}</p><div class="qty"><button data-qty="${x.id}|${x.size}|-1" aria-label="Decrease quantity">−</button><span>${x.qty}</span><button data-qty="${x.id}|${x.size}|1" aria-label="Increase quantity" ${x.qty>=x.p.stock[x.size]?'disabled':''}>+</button></div><button class="mini muted" data-remove="${x.id}|${x.size}">Remove</button></div><strong>${money(x.p.price*x.qty)}</strong></div>`).join('')}</div><aside class="panel" style="align-self:start">${orderSummary()}</aside></div>`:'<div class="empty"><h2>A little room for something good.</h2><p class="muted">Your bag is empty. Find your next everyday essential.</p><a class="btn" href="#/shop">Explore the collection ↗</a></div>'}</main>`;}
function checkout(){if(!db.cart.length)return cart();if(!db.user||db.user.role!=='Customer')return `<main class="container"><div class="empty"><h2>Your next step: customer login.</h2><p>Choose Demo Customer to try a complete purchase.</p><a class="btn" href="#/login">Continue to login</a></div></main>`;return `<main class="container"><div class="page-title"><div><div class="eyebrow">One last step</div><h1>Make it yours.</h1><p>Demo checkout · Please use sample contact and address details.</p></div></div><div class="cart-layout"><form id="checkout-form" class="panel"><h3>01 / Customer details</h3><div class="checkout-fields">${field('Name','name','text',db.user.name,true)}${field('Email','email','email',db.user.email,true)}${field('Phone number','phone','tel','9876543210',true,'pattern="[0-9]{10}" minlength="10" maxlength="10"')}</div><h3>02 / Delivery address</h3><div class="checkout-fields">${field('Address','address','text','24 Sample Lane',true)}${field('City','city','text','New Delhi',true)}${field('State','state','text','Delhi',true)}${field('PIN code','pin','text','110001',true,'pattern="[0-9]{6}" maxlength="6"')}</div><h3>03 / Payment method</h3><div class="field"><label for="payment">Simulated payment only</label><select id="payment" name="payment">${['UPI','Debit Card','Credit Card','Cash on Delivery'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="info">No UPI ID, card number, or bank details are required. Payment is simulated. Cash on delivery orders are recorded as payment due.</div><div class="spacer"></div><button class="btn full" type="submit">Place demo order · ${money(cartTotals().total)} ↗</button></form><aside class="panel" style="align-self:start">${orderSummary(false)}${cartItems().map(x=>`<div class="line"><span>${esc(x.p.name)} · ${x.size} × ${x.qty}</span><span>${money(x.p.price*x.qty)}</span></div>`).join('')}</aside></div></main>`;}
function placeOrder(form){const f=new FormData(form);if(!db.user||db.user.role!=='Customer')return toast('Please sign in as a customer.');let stored;try{stored=JSON.parse(localStorage.getItem(KEY));}catch{}if(stored){db.products=stored.products;db.orders=stored.orders;db.customers=stored.customers;}let items=cartItems();if(!items.length||items.length!==db.cart.length)return toast('A product has changed. Review your bag.');if(items.some(x=>!x.p.stock[x.size]||x.qty>x.p.stock[x.size])){toast('Stock changed. Please adjust your bag before checkout.');location.hash='/cart';return;}const totals=cartTotals(),customer={name:f.get('name').trim(),email:f.get('email').trim().toLowerCase()},order={id:'ORD-'+new Date().getFullYear()+'-'+(Math.max(1000,...db.orders.map(o=>Number(o.id.split('-').pop())))+1),date:new Date().toISOString(),customer,items:items.map(x=>({id:x.id,name:x.p.name,category:x.p.category,size:x.size,qty:x.qty,price:x.p.price,cost:x.p.cost})),...totals,payment:f.get('payment'),status:f.get('payment')==='Cash on Delivery'?'Payment due':'Paid',delivery:{address:f.get('address'),city:f.get('city'),state:f.get('state'),pin:f.get('pin'),phone:f.get('phone')}};items.forEach(x=>x.p.stock[x.size]-=x.qty);db.orders.push(order);if(!db.customers.some(c=>c.email===customer.email))db.customers.push(customer);db.cart=[];save();location.hash='/success/'+order.id;}
function success(){const o=db.orders.find(o=>o.id===route.split('/')[2]);if(!o)return'<main class="container"><div class="empty">Order not found.</div></main>';return `<main class="container"><section class="panel success"><div class="success-icon">✓</div><div class="eyebrow">${o.status==='Paid'?'Simulated payment successful':'Order confirmed · Pay on delivery'}</div><h1 style="font-size:36px">A good choice, ${esc(o.customer.name.split(' ')[0])}.</h1><p class="muted">Your order is confirmed. Inventory, sales, and management reports have all been updated.</p><div class="report-summary" style="justify-content:center"><span>Order number<strong>${o.id}</strong></span><span>Order total<strong>${money(o.total)}</strong></span><span>Payment<strong>${o.payment}</strong></span></div>${o.items.map(x=>`<div class="line"><span>${esc(x.name)} · ${x.size} × ${x.qty}</span><span>${money(x.price*x.qty)}</span></div>`).join('')}<div class="spacer"></div><a class="btn" href="#/shop">Continue exploring ↗</a> <a class="btn secondary" href="#/admin">See the business impact</a></section></main>`;}
function field(label,name,type='text',value='',required=false,extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;}
function login(){return `<main class="container"><div class="page-title" style="text-align:center;display:block"><div class="eyebrow">One store. Two perspectives.</div><h1>Welcome to StyleSphere.</h1><p>Shop the collection or explore the business behind it.</p></div>${db.user?`<div class="info" style="max-width:875px;margin:auto">Signed in as ${esc(db.user.name)} · ${db.user.role}. <button class="text-btn" id="logout">Sign out</button></div>`:''}<div class="demo-credentials" style="max-width:875px;margin:18px auto"><strong>Demo login details</strong><br>Customer: <code>customer@stylesphere.demo</code> / <code>customer123</code><br>Admin: <code>admin@stylesphere.demo</code> / <code>admin123</code><br><span class="muted">You can also use the one-click Demo Login buttons below.</span></div><div class="login-grid">${['Customer','Admin'].map(role=>`<form class="login-card" data-login="${role}"><div class="eyebrow">${role==='Customer'?'01 / The wardrobe':'02 / The business'}</div><h2>${role==='Customer'?'Find your everyday.':'See the bigger picture.'}</h2><p class="muted mini">${role==='Customer'?'Browse, build your bag, and try a demo purchase.':'Manage products, understand sales, and make better decisions.'}</p>${role==='Customer'?field('Name','customer-name','text','',true):''}${field(role+' email',role.toLowerCase()+'-email','email','',true)}${field('Password',role.toLowerCase()+'-password','password','',true,'minlength="4" autocomplete="off"')}<button class="btn full">Enter as ${role}</button><div style="text-align:center;margin:15px 0" class="mini muted">or explore in one click</div><button type="button" class="btn secondary full" data-demo="${role}">Demo ${role} Login ↗</button></form>`).join('')}</div><p class="notice" style="text-align:center">Demonstration role selection, not secure authentication. Any valid demo details work. Passwords are never saved.</p></main>`;}
function signIn(role,name,email){db.user={role,name,email};save();toast('Welcome, '+name);location.hash=role==='Admin'?'/admin':db.cart.length?'/cart':'/shop';render();}
function allLines(){return db.orders.flatMap(o=>o.items.map(i=>({...i,date:o.date,orderId:o.id})));}function bestProducts(){let lines=allLines();return db.products.map(p=>({p,qty:sum(lines.filter(x=>x.id===p.id).map(x=>x.qty))})).sort((a,b)=>b.qty-a.qty);}
function metrics(lines=allLines()){const revenue=sum(lines.map(x=>x.qty*x.price)),cogs=sum(lines.map(x=>x.qty*x.cost)),expenses=sum(Object.values(db.expenses));return{revenue,cogs,expenses,gross:revenue-cogs,net:revenue-cogs-expenses,margin:revenue?(revenue-cogs-expenses)/revenue*100:0,units:sum(lines.map(x=>x.qty)),stock:sum(db.products.map(totalStock)),value:sum(db.products.map(p=>totalStock(p)*p.cost)),low:db.products.flatMap(p=>Object.values(p.stock)).filter(q=>q>0&&q<5).length,out:db.products.flatMap(p=>Object.values(p.stock)).filter(q=>q===0).length};}
const adminLinks=[['Overview','/admin','◫'],['Inventory','/admin/inventory','▦'],['Products','/admin/products','◇'],['Orders','/admin/orders','▤'],['Customers','/admin/customers','♧'],['Reports','/admin/reports','▥'],['Finances','/admin/finances','₹'],['AI insights','/admin/insights','✧']];
function adminShell(content){return `<div class="admin-shell"><aside class="sidebar">${brand()}<div class="side-label">WORKSPACE</div><nav class="side-nav">${adminLinks.map(([n,r,i])=>`<a href="#${r}" class="${route===r?'active':''}"><span class="icon">${i}</span>${n}</a>`).join('')}</nav><div class="side-label">LEARN & EXPLORE</div><nav class="side-nav"><a href="#/admin/concepts" class="${route.endsWith('/concepts')?'active':''}"><span class="icon">◉</span>Financial concepts</a><a href="#/admin/flow" class="${route.endsWith('/flow')?'active':''}"><span class="icon">⇄</span>System flow</a><a href="#/"><span class="icon">↗</span>Visit storefront</a></nav><div class="sidebar-bottom"><div class="info">Store management<br><span class="mini">All data is saved in this browser.</span></div></div></aside><div class="admin-main"><header class="admin-top"><span class="muted">StyleSphere / Business workspace</span><div style="display:flex;align-items:center;gap:12px"><span class="tag">Demo · Admin</span><span class="avatar">${esc(db.user.name.slice(0,2).toUpperCase())}</span><a href="#/login">${esc(db.user.name)}</a></div></header><main class="admin-content">${content}</main></div></div>`;}
function title(eyebrow,h,p,button=''){return `<div class="page-title"><div><div class="eyebrow" style="margin-bottom:11px">${eyebrow}</div><h1>${h}</h1><p>${p}</p></div>${button}</div>`;}
function stat(label,value,foot,tooltip=''){return `<div class="stat"><div class="stat-label">${label}${tooltip?`<button class="info-button" title="${esc(tooltip)}" data-info="${esc(tooltip)}" aria-label="Explain ${label}">ⓘ</button>`:'<span>↗</span>'}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function categoryData(lines=allLines()){return CATS.map(c=>({name:c,qty:sum(lines.filter(x=>x.category===c).map(x=>x.qty)),revenue:sum(lines.filter(x=>x.category===c).map(x=>x.qty*x.price))}));}function bars(data,key='revenue'){const max=Math.max(1,...data.map(x=>x[key]));return data.map((x,i)=>`<div class="bar-item"><div class="bar-top"><span>${x.name}</span><strong>${key==='revenue'?money(x[key]):x[key]+' units'}</strong></div><div class="track"><div class="fill" style="width:${x[key]/max*100}%;opacity:${1-i*.14}"></div></div></div>`).join('');}
function salesChart(){let days=Array.from({length:8},(_,i)=>{let start=new Date();start.setDate(start.getDate()-(7-i)*7-6);start.setHours(0,0,0,0);let end=new Date(start);end.setDate(end.getDate()+7);return {label:start.toLocaleDateString('en-IN',{day:'numeric',month:'short'}),value:sum(db.orders.filter(o=>new Date(o.date)>=start&&new Date(o.date)<end).map(o=>o.subtotal))};});let max=Math.max(1,...days.map(d=>d.value));return `<div class="chart">${days.map(d=>`<div class="chart-col"><span class="value">${money(d.value)}</span><div class="chart-bar" style="height:${d.value/max*88}%" title="${d.label}: ${money(d.value)}"></div><small>${d.label}</small></div>`).join('')}</div>`;}
function overview(){const m=metrics();return title('Your business, at a glance','A little clarity. A lot of possibility.','Here’s how your store is doing. Every number comes from your live demo data.',`<a class="btn" href="#/admin/reports">View reports ↗</a>`)+`<div class="stats">${stat('Total sales revenue',money(m.revenue),'Excluding GST · all orders')}${stat('Total orders',db.orders.length,m.units+' individual pieces sold')}${stat('Available inventory',m.stock,db.products.length+' products in the collection')}${stat('Low stock variants',m.low,m.out+' size variants out of stock')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h3>Sales at a glance</h3><span class="tag">Last 8 weeks</span></div><div style="font-size:24px;margin-bottom:4px">${money(m.revenue)}</div><span class="mini muted">All-time sales, excluding GST</span>${salesChart()}</section><section class="panel"><div class="panel-title"><h3>Category performance</h3><span class="mini muted">Revenue</span></div>${bars(categoryData())}<a class="text-btn" href="#/admin/reports">Explore category reports ↗</a></section></div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h3>Recent orders</h3><a class="mini" href="#/admin/orders">View all ↗</a></div>${orderTable(db.orders.slice(-5).reverse())}</section><section class="panel" style="background:#f0f3e9"><div class="panel-title"><h3>✧ Business insights</h3><span class="tag">Data driven</span></div>${insights().slice(0,3).map(insightCard).join('')}<a class="text-btn" href="#/admin/insights">See all insights ↗</a></section></div><div class="stats">${stat('Registered customers',db.customers.length,'Unique demo email addresses')}${stat('Gross profit',money(m.gross),'Sales revenue − cost of goods')}${stat('Net profit',money(m.net),'After operating expenses')}${stat('Stock value at cost',money(m.value),'Current quantity × unit cost')}</div>`;}
function orderTable(orders){return table(['Order','Customer','Date','Amount','Status'],orders.map(o=>[o.id,esc(o.customer.name),new Date(o.date).toLocaleDateString('en-IN'),money(o.total),`<span class="tag ${o.status==='Paid'?'':'low'}">${o.status}</span>`]));}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" style="text-align:center;padding:35px">No matching records.</td></tr>`}</tbody></table></div>`;}
function variantRows(){const lines=allLines();return db.products.flatMap(p=>Object.entries(p.stock).map(([size,qty])=>({p,size,qty,sold:sum(lines.filter(x=>x.id===p.id&&x.size===size).map(x=>x.qty)),opening:p.opening[size]||0,adjustment:p.adjustments[size]||0})));}
function inventory(){return title('Stockroom','Every piece, accounted for.','Track sizes, stock movements, and what needs replenishing.',`<button class="btn" data-export-inventory>Export inventory ↓</button>`)+`<div class="filters"><input type="search" id="inventory-search" placeholder="Search products or codes…" aria-label="Search inventory"><select id="inventory-status" aria-label="Stock status"><option value="">All stock statuses</option><option>In Stock</option><option>Low Stock</option><option>Out of Stock</option></select></div><section class="panel" id="inventory-table"></section><p class="notice">Opening stock + manual adjustments − all units sold = available stock. Low stock means 1–4 units per size.</p>`;}
function filteredInventory(){const q=$('#inventory-search')?.value.toLowerCase()||'',status=$('#inventory-status')?.value||'';return variantRows().filter(x=>(x.p.name+' '+x.p.id).toLowerCase().includes(q)&&(!status||stockStatus(x.qty)===status));}
function inventoryTable(){let rows=filteredInventory();$('#inventory-table').innerHTML=table(['Product / ID','Category','Size','Opening','Adjusted','Sold','Available','Price','Value at cost','Status',''],rows.map(x=>[`${esc(x.p.name)}<br><span class="mini muted">${x.p.id}</span>`,x.p.category,x.size,x.opening,(x.adjustment>0?'+':'')+x.adjustment,x.sold,x.qty,money(x.p.price),money(x.qty*x.p.cost),stockTag(x.qty),`<button class="text-btn" data-edit="${x.p.id}">Edit</button>`]));}
function productManagement(){return title('The collection','Thoughtfully curated. Easily managed.','Create products, set costs and prices, and maintain size-level stock.',`<button class="btn" id="new-product">+ Add product</button>`)+`<section class="panel">${table(['Product','Code','Category','Price','Unit cost','Available','Actions'],db.products.map(p=>[`<span class="thumb">${art(p)}</span>${esc(p.name)}`,p.id,p.category,money(p.price),money(p.cost),totalStock(p),`<button class="text-btn" data-edit="${p.id}">Edit</button> <button class="mini muted" data-delete="${p.id}">Delete</button>`]))}</section>`;}
function editProduct(id){const p=db.products.find(p=>p.id===id);const ps=p||{name:'',category:'Men',type:'T-Shirts',price:999,cost:500,color:'#8f9b80',shape:'tee',stock:Object.fromEntries(SIZES.map(s=>[s,10])),description:''};modal(`<h2>${p?'Edit '+esc(p.name):'Add a considered essential'}</h2><p class="mini muted">Changes update storefront stock and inventory reports instantly.</p><form id="product-form"><div class="checkout-fields">${field('Product name','name','text',ps.name,true,'maxlength="70"')}${field('Product code','code','text',p?.id||'Assigned automatically',false,'disabled')}<div class="field"><label for="pcategory">Category</label><select name="category" id="pcategory">${CATS.map(c=>`<option ${ps.category===c?'selected':''}>${c}</option>`).join('')}</select></div>${field('Product type','type','text',ps.type,true)}${field('Selling price (₹)','price','number',ps.price,true,'min="1" step="1"')}${field('Cost per unit (₹)','cost','number',ps.cost,true,'min="0" step="1"')}${field('Illustration colour','color','color',ps.color)}<div class="field"><label for="shape">Product illustration</label><select id="shape" name="shape">${['tee','shirt','jeans','jacket','dress','kurti','set','bag','belt','cap','scarf'].map(s=>`<option ${ps.shape===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="field"><label for="description">Description</label><textarea id="description" name="description" rows="3" required>${esc(ps.description)}</textarea></div><h3>Available units by size</h3><div id="stock-inputs" class="checkout-fields"></div><p class="notice">Setting available quantities creates an inventory adjustment. Historical sales and costs are preserved. Sold sizes must remain in inventory.</p><div class="spacer"></div><button class="btn full">Save product ↗</button></form>`);const stockFields=()=>{$('#stock-inputs').innerHTML=([...new Set([...Object.keys(p?.stock||{}),...($('#pcategory').value==='Accessories'?['One Size']:SIZES)])]).map(s=>field(s,'stock_'+s,'number',ps.stock[s]??0,true,'min="0" max="100000" step="1"')).join('');};stockFields();$('#pcategory').onchange=stockFields;$('#product-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),stock={};for(const [k,v]of f)if(k.startsWith('stock_'))stock[k.slice(6)]=Number(v);if(Object.values(stock).some(v=>!Number.isInteger(v)||v<0))return toast('Stock must be a nonnegative whole number.');const data={name:f.get('name').trim(),category:f.get('category'),type:f.get('type').trim(),price:Number(f.get('price')),cost:Number(f.get('cost')),color:f.get('color'),shape:f.get('shape'),description:f.get('description').trim(),stock};if(!data.name||!data.description)return toast('Please enter a name and description.');if(p){for(const s in stock){p.adjustments[s]=(p.adjustments[s]||0)+stock[s]-(p.stock[s]||0);p.opening[s]??=0;}Object.assign(p,data);}else{db.products.push({...data,id:'SS-'+Date.now().toString().slice(-7),opening:{...stock},adjustments:Object.fromEntries(Object.keys(stock).map(s=>[s,0]))});}save();closeModal();render();toast('Product and inventory updated');};}
function deleteProduct(id){const p=db.products.find(p=>p.id===id);modal(`<h2>Remove ${esc(p.name)}?</h2><p class="muted">This removes the product from the collection and current inventory. Historical orders, sales, and profit records remain available.</p><div class="info">${totalStock(p)} remaining units will no longer appear in active inventory. This represents removing the product from the demo catalogue.</div><div class="spacer"></div><button class="btn danger" id="confirm-delete">Delete product</button> <button class="btn secondary" data-close>Keep product</button>`,true);$('#confirm-delete').onclick=()=>{db.products=db.products.filter(x=>x.id!==id);db.cart=db.cart.filter(x=>x.id!==id);save();closeModal();render();toast('Product removed; historical sales retained');};}
function ordersPage(){return title('Transactions','Every order tells a story.','Orders include GST. Revenue reports exclude GST; COD orders are recorded as payment due.')+`<section class="panel">${orderTable([...db.orders].reverse())}</section>`;}
function customersPage(){return title('People','The people behind the purchases.','Customer records connected to order history and lifetime spend.')+`<section class="panel">${table(['Customer','Email','Orders','Total order value','Latest order'],db.customers.map(c=>{let orders=db.orders.filter(o=>o.customer.email===c.email);return[esc(c.name),esc(c.email),orders.length,money(sum(orders.map(o=>o.total))),orders.length?new Date(orders.at(-1).date).toLocaleDateString('en-IN'):'—'];}))}</section>`;}
function reports(){return title('Management reports','From information to better decisions.','Filter your data, compare performance, and take the report with you.',`<div style="display:flex;gap:8px"><button class="btn secondary" id="print-report">Print / PDF</button><button class="btn" id="download-report">Download CSV ↓</button></div>`)+`<div class="tabs">${[['sales','Sales report'],['size','By size'],['category','By category'],['inventory','Inventory report']].map(([v,n])=>`<button data-report="${v}" class="${reportType===v?'active':''}">${n}</button>`).join('')}</div><form id="report-filters" class="filters"><select name="category" aria-label="Report category"><option value="">All categories</option>${CATS.map(c=>`<option>${c}</option>`).join('')}</select><select name="product" aria-label="Report product"><option value="">All products</option>${[...new Map([...db.products.map(p=>[p.id,p.name]),...allLines().map(p=>[p.id,p.name])]).entries()].map(([id,n])=>`<option value="${id}">${esc(n)}</option>`).join('')}</select><select name="size" aria-label="Report size"><option value="">All sizes</option>${[...SIZES,'One Size'].map(s=>`<option>${s}</option>`).join('')}</select><select name="status" aria-label="Report stock status"><option value="">All stock statuses</option><option>In Stock</option><option>Low Stock</option><option>Out of Stock</option></select><label class="mini">From <input type="date" name="from" aria-label="From date"></label><label class="mini">To <input type="date" name="to" aria-label="To date"></label><button class="btn small">Generate report ↗</button></form><div id="report-output"></div>`;}
function generateReport(){const f=Object.fromEntries(new FormData($('#report-filters')));if(f.from&&f.to&&f.from>f.to)return toast('The end date must follow the start date.');let lines=allLines().filter(x=>{const localDate=new Date(x.date).toLocaleDateString('en-CA');return(!f.category||x.category===f.category)&&(!f.product||x.id===f.product)&&(!f.size||x.size===f.size)&&(!f.from||localDate>=f.from)&&(!f.to||localDate<=f.to)&&(!f.status||stockStatus(db.products.find(p=>p.id===x.id)?.stock[x.size]??0)===f.status);});let variants=variantRows().filter(x=>(!f.category||x.p.category===f.category)&&(!f.product||x.p.id===f.product)&&(!f.size||x.size===f.size)&&(!f.status||stockStatus(x.qty)===f.status));let rows=[],headers=[],extra='',qty=sum(lines.map(x=>x.qty)),rev=sum(lines.map(x=>x.qty*x.price)),available=sum(variants.map(x=>x.qty));const aggregate=(field)=>[...new Set(lines.map(x=>x[field]))].map(n=>({name:n,qty:sum(lines.filter(x=>x[field]===n).map(x=>x.qty)),revenue:sum(lines.filter(x=>x[field]===n).map(x=>x.qty*x.price))})).sort((a,b)=>b.qty-a.qty);const productRank=aggregate('name'),sizeRank=aggregate('size'),catRank=aggregate('category');if(reportType==='sales'){headers=['Product','Category','Size','Qty sold','Available now','Avg selling price','Sales revenue'];const keys=[...new Set([...variants.map(x=>x.p.id+'|'+x.size),...lines.map(x=>x.id+'|'+x.size)])];rows=keys.map(k=>{let[id,size]=k.split('|'),l=lines.filter(x=>x.id===id&&x.size===size),p=db.products.find(x=>x.id===id),q=sum(l.map(x=>x.qty)),r=sum(l.map(x=>x.qty*x.price));return[p?.name||l[0]?.name||id,p?.category||l[0]?.category,size,q,p?.stock[size]||0,q?money(r/q):'—',money(r)];});extra=`<div class="report-summary"><span>Best selling product<strong>${esc(productRank[0]?.name||'—')}</strong></span><span>Best category by units<strong>${catRank[0]?.name||'—'}</strong></span><span>Most sold size<strong>${sizeRank[0]?.name||'—'}</strong></span><span>Lowest selling active product<strong>${esc(db.products.filter(p=>(!f.category||p.category===f.category)&&(!f.product||p.id===f.product)).map(p=>({name:p.name,q:sum(lines.filter(x=>x.id===p.id).map(x=>x.qty))})).sort((a,b)=>a.q-b.q)[0]?.name||'—')}</strong></span></div>`;}else if(reportType==='size'){headers=['Size','Units sold','Units available now','Revenue'];rows=[...SIZES,'One Size'].filter(s=>!f.size||s===f.size).map(s=>[s,sum(lines.filter(x=>x.size===s).map(x=>x.qty)),sum(variants.filter(x=>x.size===s).map(x=>x.qty)),money(sum(lines.filter(x=>x.size===s).map(x=>x.qty*x.price)))]);extra=`<div class="info">Most sold size: <strong>${sizeRank[0]?.name||'No sales in this period'}</strong>. Size comparisons use units sold in the selected period.</div>`;}else if(reportType==='category'){headers=['Category','Units sold','Revenue'];rows=categoryData(lines).filter(c=>!f.category||c.name===f.category).map(c=>[c.name,c.qty,money(c.revenue)]);extra=`<section class="panel" style="max-width:700px;margin-top:20px">${bars(categoryData(lines))}</section>`;}else{headers=['Product','Size','Opening stock','Adjustments','Sold all time','Remaining now','Value at cost','Status'];rows=variants.map(x=>[x.p.name,x.size,x.opening,x.adjustment,x.sold,x.qty,money(x.qty*x.p.cost),stockStatus(x.qty)]);extra=`<div class="report-summary"><span>Opening stock<strong>${sum(variants.map(x=>x.opening))}</strong></span><span>Manual adjustments<strong>${sum(variants.map(x=>x.adjustment))}</strong></span><span>Stock value<strong>${money(sum(variants.map(x=>x.qty*x.p.cost)))}</strong></span><span>Low / out of stock variants<strong>${variants.filter(x=>x.qty>0&&x.qty<5).length} / ${variants.filter(x=>!x.qty).length}</strong></span></div>`;}const note=reportType==='inventory'?'Inventory is a current snapshot. Dates apply only to the period sales summary; opening and sold columns cover all time.':'Sales are filtered by order date. Available quantities and stock status always reflect current inventory. Revenue excludes GST.';lastReport={headers,rows,type:reportType,filters:f};$('#report-output').innerHTML=`<div class="panel"><div class="panel-title"><h3>${{sales:'Detailed sales',size:'Size-wise sales',category:'Category performance',inventory:'Inventory position'}[reportType]}</h3><span class="mini muted">Generated ${new Date().toLocaleDateString('en-IN')}</span></div><p class="mini muted">${esc(f.from||'All time')} → ${esc(f.to||'Today')} · ${esc(f.category||'All categories')} · ${esc(f.size||'All sizes')}</p><div class="report-summary"><span>Quantity sold in period<strong>${qty}</strong></span><span>Quantity available now<strong>${available}</strong></span><span>Revenue in period<strong>${money(rev)}</strong></span></div>${table(headers,rows.map(r=>r.map(esc)))}${extra}<p class="notice">${note}</p></div>`;}
const terms=[['Revenue','Money earned from garment sales, before deducting costs. GST collected is kept separate.','100 shirts × ₹800 = ₹80,000 revenue'],['Cost of Goods Sold (COGS)','The purchase or manufacturing cost of garments actually sold. Unsold goods remain inventory.','100 shirts × ₹500 cost = ₹50,000 COGS'],['Gross Profit','What remains from sales after paying for the garments sold.','Revenue − COGS = ₹80,000 − ₹50,000 = ₹30,000'],['Operating Expenses','The costs of running the store: rent, electricity, salaries, advertising, internet, and software.','Example: rent ₹18,000 + salaries ₹24,000 + other costs'],['Net Profit','What remains after garment costs and operating expenses. This simplified demo excludes other taxes and financing costs.','Revenue − COGS − operating expenses'],['Profit Margin','The percentage of revenue retained as profit. Specify gross or net profit when comparing margins.','Profit ÷ Revenue × 100; ₹30,000 ÷ ₹80,000 = 37.5%'],['Inventory','All garments and accessories currently available for sale, tracked separately by size.','12 small + 15 medium + 10 large shirts = 37 units'],['Inventory Value','The value of stock still on hand, measured at its purchase cost, not its selling price.','Available quantity × cost per unit; 37 × ₹500 = ₹18,500'],['Sales','The units or value of products sold in a period. Orders, units, and revenue are different measures.','One order can contain 3 items and generate ₹2,400 revenue'],['Expenses','Money spent to earn revenue and operate the business; includes COGS and operating costs.','Total expenses = cost of goods sold + operating expenses'],['Break-Even Point','The sales level where revenue covers all costs. Below it the store makes a loss; above it, a profit.','Break-even units = fixed costs ÷ (unit price − unit variable cost)'],['GST / Tax','Tax is added to the customer subtotal. This assignment uses a fixed illustrative 5% rate; it is not store revenue.','₹2,000 subtotal + ₹100 demo GST = ₹2,100 order total']];
function concepts(){return title('Learn the language of business','Finance, without the jargon.','Simple definitions, connected to everyday decisions at StyleSphere.')+`<div class="grid2">${terms.map(([t,d,e])=>`<article class="concept"><h3>${t}</h3><p>${d}</p><div class="formula">${e}</div></article>`).join('')}</div>`;}
function finances(){const m=metrics(),tax=sum(db.orders.map(o=>o.tax)),due=sum(db.orders.filter(o=>o.status==='Payment due').map(o=>o.total));return title('Financial workspace','Know what your business earns.','All-time demo ledger · sales recognised on order confirmation, including COD.')+`<div class="stats">${stat('Sales revenue',money(m.revenue),'Before tax',terms[0][1])}${stat('Cost of goods sold',money(m.cogs),'Historical unit costs',terms[1][1])}${stat('Gross profit',money(m.gross),'Revenue − COGS',terms[2][1])}${stat('Operating expenses',money(m.expenses),'Editable below',terms[3][1])}${stat('Net profit',money(m.net),'Gross profit − expenses',terms[4][1])}${stat('Net profit margin',m.margin.toFixed(1)+'%','Net profit ÷ revenue × 100',terms[5][1])}${stat('Inventory value',money(m.value),'Available units × cost',terms[7][1])}${stat('GST collected / due',money(tax),'Excluded from revenue',terms[11][1])}</div><div class="grid2"><section class="panel"><h3>The numbers, made clear.</h3><div class="line"><span>Sales revenue</span><strong>${money(m.revenue)}</strong></div><div class="line"><span>− Cost of goods sold</span><span>${money(m.cogs)}</span></div><div class="line total"><span>Gross profit</span><strong>${money(m.gross)}</strong></div><div class="line"><span>− Operating expenses</span><span>${money(m.expenses)}</span></div><div class="line total"><span>Net profit</span><strong>${money(m.net)}</strong></div><div class="info">Gross margin: ${m.revenue?(m.gross/m.revenue*100).toFixed(1):0}%<br>COD amount receivable, including GST: ${money(due)}<br>Revenue represents confirmed sales, not cash received.</div></section><form class="panel expense-list" id="expense-form"><h3>Operating expenses</h3><p class="mini muted">Set total expenses for the full demo reporting period.</p>${Object.entries(db.expenses).map(([k,v])=>`<label class="line"><span>${k}</span><input aria-label="${k} expense" name="${k}" type="number" min="0" step="1" required value="${v}"></label>`).join('')}<div class="spacer"></div><button class="btn full">Update expenses</button><p class="notice">Changing expenses recalculates net profit and margin instantly.</p></form></div>`;}
function insights(){const m=metrics(),cats=categoryData().sort((a,b)=>b.revenue-a.revenue),sizes=[...SIZES,'One Size'].map(s=>({s,q:sum(allLines().filter(x=>x.size===s).map(x=>x.qty))})).sort((a,b)=>b.q-a.q),low=variantRows().filter(x=>x.qty<5).sort((a,b)=>a.qty-b.qty),best=bestProducts()[0];return [{title:'Your strongest category',text:cats[0].revenue?`${cats[0].name} leads with ${money(cats[0].revenue)} in revenue. Review this category for replenishment and merchandising.`:'There are no recorded sales yet.'},{title:'Buy with size demand in mind',text:sizes[0].q?`Size ${sizes[0].s} is the most purchased with ${sizes[0].q} units sold. Compare its remaining stock before placing your next purchase order.`:'Complete an order to see size demand.'},{title:low.length?'A stockroom check is due':'Stock is well balanced',text:low.length?`${low[0].p.name}, size ${low[0].size}, has ${low[0].qty} units remaining. ${low.length} variants are below the 5-unit reorder threshold.`:'All active variants have at least 5 units available.'},{title:'The profit perspective',text:`Gross profit is ${money(m.gross)}, with a ${m.revenue?(m.gross/m.revenue*100).toFixed(1):0}% gross margin. After operating expenses, net profit is ${money(m.net)}.`},{title:'Your customer favourite',text:best?.qty?`${best.p.name} leads active products with ${best.qty} units sold. Keep popular sizes available and feature it in your collection.`:'No active product has recorded sales yet.'},{title:'Working capital in the stockroom',text:`Current stock has a cost value of ${money(m.value)} across ${m.stock} units. Compare sales velocity before increasing slower-moving stock.`}];}
function insightCard(x){return `<article class="insight"><span class="insight-icon">✧</span><div><h4>${x.title}</h4><p>${esc(x.text)}</p></div></article>`;}
function insightsPage(){return title('AI business insights','A clearer next move.','Recommendations generated from your current sales, size demand, inventory, and finances.')+`<div class="info" style="margin-bottom:22px">Transparent demo: these insights use deterministic rules and calculations, not an external AI model. They refresh automatically when your store data changes.</div><div class="grid2">${insights().map(x=>`<section class="panel">${insightCard(x)}</section>`).join('')}</div>`;}
function flow(){const steps=[['Customer','A customer signs in and explores the collection.'],['Select category','Products are organised by Men, Women, Kids, and Accessories.'],['Choose product & size','Size-level availability prevents out-of-stock selections.'],['Add to cart','The cart combines quantities, prices, and an illustrative GST amount.'],['Checkout','Demo contact and delivery information accompany the order.'],['Simulate payment','UPI, cards, or COD; no actual money or bank data.'],['Generate order','A unique order ID connects the customer and purchase line items.'],['Update inventory','Purchased quantities are deducted from the selected size.'],['Store sales data','Unit prices and unit costs are captured at purchase time.'],['Refresh dashboard','Sales, units, and available inventory use the same shared records.'],['Generate reports','Sales, size, category, inventory, and profit are calculated.'],['Make a decision','Management can identify demand, reorder, and manage expenses.']];return title('How StyleSphere works','One purchase. A connected business.','Follow the journey from raw transaction data to a useful management decision.')+`<div class="flow">${steps.map(([h,p])=>`<section class="flow-step"><h3>${h}</h3><p>${p}</p></section>`).join('')}</div><section class="panel" style="margin-top:25px"><h2>How this system supports business decisions</h2><p class="muted">StyleSphere collects customer purchase data, processes it, and turns it into useful information for management.</p><div class="report-summary"><span>Input<strong>2 medium shirts purchased</strong></span><span>Processing<strong>Record sale; subtract 2 units</strong></span><span>Information<strong>Update sales & inventory</strong></span><span>Decision<strong>Reorder popular sizes</strong></span></div><p class="formula">Data → Processing → Information → Business Decision</p><p class="notice">Prototype architecture: browser-local storage is the shared ledger for this browser. Separate devices do not share records. Demo roles are not production security.</p></section>`;}
function about(){return `<main class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">About StyleSphere</div><h1>Everyday style.<br>Thoughtfully connected.</h1><p>A modern garment store where customer purchases, inventory, and business decisions stay connected.</p><a class="btn" href="#/flow">Explore the system ↗</a></div><div class="hero-art">${art({name:'StyleSphere everyday tote',shape:'bag',color:'#899379'})}</div></section><div class="section-head"><h2>A store with a bigger story.</h2></div><div class="grid2"><section class="panel"><h3>For the customer</h3><p class="muted">Browse a considered collection of apparel and accessories, find the right size, and experience a complete simulated purchase.</p></section><section class="panel"><h3>For the business</h3><p class="muted">Follow every sale through inventory, reporting, and financial performance. Turn everyday transactions into informed management decisions.</p></section></div></main>`;}
function modal(content,narrow=false){$('#overlay').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="StyleSphere dialog" class="modal ${narrow?'narrow':''}" tabindex="-1"><button class="close" data-close aria-label="Close dialog">×</button>${content}</section></div>`;document.body.style.overflow='hidden';$('.modal').focus();}function closeModal(){$('#overlay').innerHTML='';document.body.style.overflow='';}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function csv(headers,rows,filename){const quote=v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@\-]/,"'$&")+'"';const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV report downloaded');}
function render(){route=location.hash.slice(1)||'/';closeModal();if(route.startsWith('/admin')&&db.user?.role!=='Admin'){$('#app').innerHTML=nav()+`<main class="container"><section class="empty"><div class="eyebrow">The business workspace</div><h1 style="font-size:36px">Step behind the collection.</h1><p class="muted">Explore sales, manage inventory, and turn your data into decisions.</p><button class="btn" data-demo="Admin">Demo Admin Login ↗</button> <a class="btn secondary" href="#/login">Choose a role</a><p class="notice">Demo access. No account required.</p></section></main>`+footer();bind();return;}if(route.startsWith('/admin')){const pages={'/admin':overview,'/admin/inventory':inventory,'/admin/products':productManagement,'/admin/orders':ordersPage,'/admin/customers':customersPage,'/admin/reports':reports,'/admin/finances':finances,'/admin/insights':insightsPage,'/admin/concepts':concepts,'/admin/flow':flow};$('#app').innerHTML=adminShell((pages[route]||overview)());}else{let content=route==='/'?home():route.startsWith('/shop')?shop():route==='/cart'?cart():route==='/checkout'?checkout():route.startsWith('/success/')?success():route==='/login'?login():route==='/about'?about():route==='/flow'?`<main class="container">${flow()}</main>`:route==='/concepts'?`<main class="container">${concepts()}</main>`:`<main class="container"><div class="empty"><h2>Page not found.</h2><a class="btn" href="#/">Return home</a></div></main>`;$('#app').innerHTML=nav()+content+footer();}bind();}
function bind(){if($('#shop-filters')){$('#shop-filters').oninput=filterShop;filterShop();}if($('#checkout-form'))$('#checkout-form').onsubmit=e=>{e.preventDefault();placeOrder(e.target);};$$('[data-login]').forEach(form=>form.onsubmit=e=>{e.preventDefault();let role=form.dataset.login,fd=new FormData(form);signIn(role,role==='Customer'?fd.get('customer-name').trim():'Store Admin',fd.get(role.toLowerCase()+'-email').trim());});if($('#logout'))$('#logout').onclick=()=>{db.user=null;save();render();toast('Signed out');};if($('#new-product'))$('#new-product').onclick=()=>editProduct();if($('#inventory-search')){$('#inventory-search').oninput=inventoryTable;$('#inventory-status').onchange=inventoryTable;inventoryTable();}if($('#report-filters')){$('#report-filters').onsubmit=e=>{e.preventDefault();generateReport();toast('Report generated from current store data');};generateReport();$('#print-report').onclick=()=>window.print();$('#download-report').onclick=()=>{if(lastReport)csv(lastReport.headers,lastReport.rows,'StyleSphere-'+lastReport.type+'-'+new Date().toISOString().slice(0,10));};}if($('#expense-form'))$('#expense-form').onsubmit=e=>{e.preventDefault();db.expenses=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));save();render();toast('Expenses and profit updated');};}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-close'))return closeModal();if(b.dataset.product)return showProduct(b.dataset.product);if(b.dataset.demo)return signIn(b.dataset.demo,b.dataset.demo==='Admin'?'Store Admin':'Demo Customer',b.dataset.demo==='Admin'?'admin@stylesphere.demo':'customer@stylesphere.demo');if(b.dataset.qty){let[id,size,d]=b.dataset.qty.split('|'),x=db.cart.find(x=>x.id===id&&x.size===size),p=db.products.find(p=>p.id===id);if(x.qty+Number(d)>p.stock[size])return toast('No more stock available in this size.');x.qty+=Number(d);if(x.qty<=0)db.cart=db.cart.filter(y=>y!==x);save();render();}if(b.dataset.remove){let[id,size]=b.dataset.remove.split('|');db.cart=db.cart.filter(x=>x.id!==id||x.size!==size);save();render();}if(b.dataset.edit&&db.user?.role==='Admin')editProduct(b.dataset.edit);if(b.dataset.delete&&db.user?.role==='Admin')deleteProduct(b.dataset.delete);if(b.dataset.report){reportType=b.dataset.report;$$('[data-report]').forEach(x=>x.classList.toggle('active',x===b));generateReport();}if(b.dataset.info)toast(b.dataset.info);if(b.hasAttribute('data-export-inventory')){const r=filteredInventory();csv(['Product','Code','Category','Size','Opening','Adjustment','Sold','Available','Price','Unit cost','Inventory value','Status'],r.map(x=>[x.p.name,x.p.id,x.p.category,x.size,x.opening,x.adjustment,x.sold,x.qty,x.p.price,x.p.cost,x.qty*x.p.cost,stockStatus(x.qty)]),'StyleSphere-inventory');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const nodes=$$('.modal button:not(:disabled),.modal input,.modal select,.modal textarea,.modal a'),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
